<# .SYNOPSIS Runs static Kerberos crypto posture and optional KDC telemetry. .NOTES Version: 1.1.0 #>
[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$EngagementDirectory,[string]$Server,[PSCredential]$Credential,[int]$LookbackDays=30,[int]$MaximumActionableAccounts=100,[int]$StalePasswordDays=730,[switch]$IncludeKdcTelemetry,[switch]$NoColor)
Set-StrictMode -Version 2.0;$ErrorActionPreference='Stop';$r=$PSScriptRoot;$telemetry=Join-Path $r 'Invoke-MSADPTKerberosEncryptionUsage.ps1';$posture=Join-Path $r 'Invoke-MSADPTKerberosAccountEncryptionPosture.ps1';$priority=Join-Path $r 'Invoke-MSADPTKerberosEncryptionPrioritization.ps1';$stages=@()
if($IncludeKdcTelemetry){try{$x=&$telemetry -EngagementDirectory $EngagementDirectory -CollectionMode Auto -LookbackDays $LookbackDays -NoColor:$NoColor;$stages+=,$x}catch{$stages+=,[pscustomobject]@{Status='Inconclusive';Disposition='Inconclusive';Error=$_.Exception.Message}}}
$p=@{EngagementDirectory=$EngagementDirectory;NoColor=$NoColor};if($Server){$p.Server=$Server};if($Credential){$p.Credential=$Credential};$s=&$posture @p;$a=&$priority -EngagementDirectory $EngagementDirectory -MaximumActionableAccounts $MaximumActionableAccounts -StalePasswordDays $StalePasswordDays -NoColor:$NoColor
[pscustomobject][ordered]@{Status='Completed';Version='1.1.0';OverallDisposition=$a.OverallDisposition;ActionableReviewCount=$a.ActionableReviewCount;TelemetryRequested=[bool]$IncludeKdcTelemetry;PrioritizedReviewPath=$a.PrioritizedReviewPath;SummaryPath=$a.SummaryPath;RemoteChanges='None';TicketRequests='None'}
